1	import { create } from "@bufbuild/protobuf";
2	import { useEffect, useMemo, useState } from "react";
3	import { memoServiceClient } from "@/connect";
4	import type { MemoRelation } from "@/types/proto/api/v1/memo_service_pb";
5	import { MemoRelation_Memo, MemoRelation_MemoSchema } from "@/types/proto/api/v1/memo_service_pb";
6	
7	export const useResolvedRelationMemos = (relations: MemoRelation[]) => {
8	  const [resolvedMemos, setResolvedMemos] = useState<Record<string, MemoRelation_Memo>>({});
9	
10	  const missingMemoNames = useMemo(() => {
11	    const names = new Set<string>();
12	
13	    for (const relation of relations) {
14	      for (const memo of [relation.memo, relation.relatedMemo]) {
15	        if (memo?.name && !memo.snippet && !resolvedMemos[memo.name]) {
16	          names.add(memo.name);
17	        }
18	      }
19	    }
20	
21	    return [...names];
22	  }, [relations, resolvedMemos]);
23	
24	  useEffect(() => {
25	    if (missingMemoNames.length === 0) {
26	      return;
27	    }
28	
29	    let cancelled = false;
30	
31	    void (async () => {
32	      try {
33	        const memos = await Promise.all(
34	          missingMemoNames.map(async (name) => {
35	            const memo = await memoServiceClient.getMemo({ name });
36	            return create(MemoRelation_MemoSchema, { name: memo.name, snippet: memo.snippet });
37	          }),
38	        );
39	
40	        if (cancelled) {
41	          return;
42	        }
43	
44	        setResolvedMemos((prev) => {
45	          const next = { ...prev };
46	          for (const memo of memos) {
47	            next[memo.name] = memo;
48	          }
49	          return next;
50	        });
51	      } catch {
52	        // Keep existing relation data when snippet hydration fails.
53	      }
54	    })();
55	
56	    return () => {
57	      cancelled = true;
58	    };
59	  }, [missingMemoNames]);
60	
61	  return resolvedMemos;
62	};
